input.command:
cd /tmp && rm -f mig_a.db mig_b.db mig_c.db
cat > /tmp/mig.sql <<'SQL'
ALTER TABLE orders ADD COLUMN status VARCHAR(20) NOT NULL DEFAULT 'pending';
CREATE INDEX idx_orders_status ON orders(status);
UPDATE orders SET status = 'fulfilled' WHERE shipped_at IS NOT NULL;
SQL

echo "=== RUN A: populated table (edge rows: NULL, epoch-zero, empty-string, future ts) ==="
sqlite3 mig_a.db <<'SQL'
CREATE TABLE orders (id INTEGER PRIMARY KEY, shipped_at TIMESTAMP);
INSERT INTO orders VALUES (1, NULL), (2, '2026-08-01 10:00:00'), (3, 0), (4, ''), (5, '2099-01-01'), (6, NULL);
.read /tmp/mig.sql
.headers on
.mode column
SELECT id, shipped_at, status FROM orders ORDER BY id;
SELECT status, COUNT(*) n FROM orders GROUP BY status;
INSERT INTO orders (id, shipped_at) VALUES (7, NULL);
SELECT id, status AS new_row_default FROM orders WHERE id = 7;
SELECT name FROM sqlite_master WHERE type='index' AND tbl_name='orders';
SQL

echo; echo "=== RUN B: empty table ==="
sqlite3 mig_b.db <<'SQL'
CREATE TABLE orders (id INTEGER PRIMARY KEY, shipped_at TIMESTAMP);
.read /tmp/mig.sql
SELECT 'rows=' || COUNT(*) FROM orders;
SQL

echo; echo "=== RUN C: re-run migration on already-migrated DB (idempotency / partial-failure retry) ==="
sqlite3 mig_a.db ".read /tmp/mig.sql" 2>&1 | head -3
